globals:
i2c_buses = {}
def i2c_bus(sda, scl, bloque):
    # Un bus por par de pines; los sensores que comparten SDA/SCL comparten el bus.
    clave = (sda, scl)
    if clave not in i2c_buses:
        try:
            if len(i2c_buses) < 2:
                i2c_buses[clave] = I2C(len(i2c_buses), scl=Pin(scl), sda=Pin(sda), freq=400000)
            else:
                i2c_buses[clave] = SoftI2C(scl=Pin(scl), sda=Pin(sda), freq=400000)
        except (ValueError, OSError) as error:
            rb_fail(bloque, "No se pudo iniciar I2C en SDA %s / SCL %s: %s" % (sda, scl, error))
    return i2c_buses[clave]
color_bus = None
def color_configurar(sda, scl, bloque):
    global color_bus
    bus = i2c_bus(sda, scl, bloque)
    try:
        if bus.readfrom_mem(0x29, 0x92, 1)[0] not in (0x44, 0x4D):
            rb_fail(bloque, "El dispositivo en 0x29 no es un TCS34725")
        bus.writeto_mem(0x29, 0x81, bytes([0xD5]))  # Integración de unos 100 ms
        bus.writeto_mem(0x29, 0x8F, bytes([0x01]))  # Ganancia 4x
        bus.writeto_mem(0x29, 0x80, bytes([0x01]))  # Encender
        time.sleep_ms(3)
        bus.writeto_mem(0x29, 0x80, bytes([0x03]))  # Encender y medir
    except OSError:
        rb_fail(bloque, "No responde el sensor de color TCS34725 (0x29)")
    color_bus = bus
def color_leer(bloque):
    if color_bus is None:
        rb_fail(bloque, "Configura el sensor de color al iniciar")
    try:
        d = color_bus.readfrom_mem(0x29, 0xB4, 8)
    except OSError:
        rb_fail(bloque, "No responde el sensor de color TCS34725")
    # Claridad, rojo, verde y azul (16 bits cada uno).
    return [d[i] | d[i + 1] << 8 for i in range(0, 8, 2)]

