def color_hsv(bloque):
    c, r, g, b = color_leer(bloque)
    brillo = min(100, c * 100 / 44032)
    mayor, menor = max(r, g, b), min(r, g, b)
    if mayor == 0:
        return 0, 0, brillo
    delta = mayor - menor
    saturacion = delta * 100 / mayor
    if delta == 0:
        tono = 0
    elif mayor == r:
        tono = 60 * ((g - b) / delta % 6)
    elif mayor == g:
        tono = 60 * ((b - r) / delta + 2)
    else:
        tono = 60 * ((r - g) / delta + 4)
    return round(tono, 1), round(saturacion, 1), round(brillo, 1)
def color_nombre(bloque):
    tono, saturacion, brillo = color_hsv(bloque)
    # Rangos aproximados: comprueba los valores de tu pista con «tono».
    if brillo < 3:
        return "negro"
    if saturacion < 20:
        return "blanco" if brillo > 20 else "gris"
    for limite, nombre in ((20, "rojo"), (45, "naranja"), (70, "amarillo"), (170, "verde"), (260, "azul"), (330, "morado")):
        if tono < limite:
            return nombre
    return "rojo"

